def test_upgrade_v2_idempotent():
    rec = {"version": 2, "id": 5, "title": "Eve", "work_mode": "remote"}
    result = models.upgrade(rec)
    assert result == rec

def test_upgrade_v2_missing_version():
    rec = {"id": 6, "title": "Frank", "work_mode": "office"}
    result = models.upgrade(rec)
    assert result == {"id": 6, "title": "Frank", "work_mode": "office", "version": 2}

